{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-huashu-luxe-whitespace",
  "title": "Write a Luxury Market-Entry Deck like a Premium-Sector Strategy Partner",
  "title_i18n": {
    "en": "Write a Luxury Market-Entry Deck like a Premium-Sector Strategy Partner",
    "zh-CN": "像高端领域战略合伙人一样写奢侈品进入市场方案",
    "zh-TW": "像高端领域战略合伙人一样写奢侈品进入市场方案"
  },
  "version": "1.0.0",
  "description": "A market-entry study for a luxury skincare brand entering Asia — segmentation, positioning, channel, and the phased plan. Built as a decision-grade consulting deck for client leadership.",
  "description_i18n": {
    "en": "A market-entry study for a luxury skincare brand entering Asia — segmentation, positioning, channel, and the phased plan. Built as a decision-grade consulting deck for client leadership.",
    "zh-CN": "像高端领域战略合伙人一样写奢侈品进入市场方案——一份可商业交付的咨询交付 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像高端领域战略合伙人一样写奢侈品进入市场方案——一份可商业交付的咨询交付 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "花叔 (alchaincyf)",
    "url": "https://github.com/alchaincyf"
  },
  "homepage": "https://github.com/alchaincyf/huashu-design",
  "plugin": {
    "repo": "https://github.com/alchaincyf/huashu-design"
  },
  "tags": [
    "community",
    "deck",
    "slides",
    "ppt",
    "presentation",
    "quiet-luxury",
    "whitespace",
    "minimal",
    "huashu",
    "consulting-deliverable",
    "strategy",
    "client",
    "huashu-luxe-whitespace",
    "consulting-delivery",
    "consulting",
    "consulting-final-deck",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "strategy",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html",
      "motion": "deck"
    },
    "useCase": {
      "query": {
        "en": "Create \"Write a Luxury Market-Entry Deck like a Premium-Sector Strategy Partner\" as a decision-grade Consulting deck in this template's own visual system. Subject: A market-entry study for a luxury skincare brand entering Asia — segmentation, positioning, channel, and the phased plan. Audience: client leadership. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: would a client know what to do Monday morning.",
        "zh-CN": "像高端领域战略合伙人一样写奢侈品进入市场方案。像高端领域战略合伙人一样写奢侈品进入市场方案——一份可商业交付的咨询交付 Deck，围绕真实主题、证据链与决策目标组织。 主题：A market-entry study for a luxury skincare brand entering Asia — segmentation, positioning, channel, and the phased plan. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Write a Luxury Market-Entry Deck like a Premium-Sector Strategy Partner",
          "title_i18n": {
            "en": "Write a Luxury Market-Entry Deck like a Premium-Sector Strategy Partner",
            "zh-CN": "像高端领域战略合伙人一样写奢侈品进入市场方案",
            "zh-TW": "像高端领域战略合伙人一样写奢侈品进入市场方案"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "deckType",
        "label": "Deck type",
        "type": "select",
        "required": true,
        "options": [
          "brand annual report deck",
          "premium product launch deck",
          "investor / board update deck",
          "quiet-luxury keynote",
          "portfolio / lookbook deck"
        ],
        "default": "brand annual report deck"
      },
      {
        "name": "topic",
        "label": "Topic",
        "type": "string",
        "required": true,
        "placeholder": "你的主题，例如：2026 品牌年度报告",
        "default": "the user's brief"
      },
      {
        "name": "audience",
        "label": "Audience",
        "type": "string",
        "required": true,
        "placeholder": "董事会 / 品牌客户 / VIP 会员",
        "default": "decision makers"
      },
      {
        "name": "slideCount",
        "label": "Pages",
        "type": "select",
        "required": true,
        "options": [
          "8 pages",
          "9-10 pages",
          "10-11 pages"
        ],
        "default": "9-10 pages"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "consulting"
  }
}
